INSERT INTO `CardData` (`language`, `type`, `text`, `flavorText`, `id`, `name`, `multiverseid`, `uuid`) VALUES ('Korean', '순간마법', replace('번개 도끼를 발동하기 위한 추가비용으로, 카드 한 장을 버리거나 {5}를 지불한다.\n생물을 목표로 정한다. 번개 도끼는 그 생물에게 피해 5점을 입힌다.','\n',char(10)), '악귀소환술사가 정신을 어지럽힌 신령은 쉴새 없이 분노하는 심령으로 변한다.', 192686, '번개 도끼', 412235, 'c194d6c3-6f56-5753-92cb-2f69d92b57cc');
