INSERT INTO `Rulings` (`uuid`, `date`, `text`, `id`) VALUES ('a654883e-3c62-58af-84f6-741a122dd832', '2015-11-04', 'Seal of the Guildpact’s last ability can’t reduce the amount of colored mana you pay for a spell. It reduces only the generic component of that cost.', 81605);
INSERT INTO `rulings` (`uuid`, `text`, `date`, `id`) VALUES ('7ff2d473-fddb-5a25-8f7a-fd5fc0578404', 'Once Hour of Devastation begins to resolve, no player may take actions until it’s done. Notably, players can’t try to give a creature indestructible again to save it from the damage.', '2017-07-14', 67029);
