INSERT INTO `MagicRulings` (`date`, `uuid`, `id`, `text`) VALUES ('2008-10-01', '91ab4603-562c-59b7-8337-6c5ef922477a', 7730, 'In a Two-Headed Giant game, a creature “attacks alone” if it’s the only creature declared as an attacker by your entire team. If you control that attacking creature, your exalted abilities will trigger but your teammate’s exalted abilities won’t.');
