INSERT INTO `CardData` VALUES ('Trespolo del Drago', 'Incantesimo', 'Italian', 168510, '{5}{R}{R}: Metti in gioco una pedina creatura Drago 5/5 rossa con volare.', 'Un potente mago ha creato il trespolo per sorvegliare un portale tra le dimensioni. Il mago è scomparso da tempo, ma i draghi sono ancora di guardia.', 165056, 'ab5cbeb2-4210-55e1-ab43-e1a33e274320');
INSERT INTO `MagicRulings` (`id`, `uuid`, `text`, `date`) VALUES (47430, 'd8df45dc-4f88-5dee-88c7-7dfa8430fbac', 'If the spell being copied targets a spell on the stack, it is possible to target Fork itself since Fork is still on the stack when you pick the target(s) for the copy. Note that the copy’s target will be illegal when it resolves.', '2004-10-04');
