INSERT INTO `MagicCards` (`id`, `language`, `flavorText`, `multiverseid`, `name`, `type`, `text`, `uuid`) VALUES (70171, 'French', 'Un sangpyre est toujours redoutable, mais si son feu est attisé par sorcellerie, il est capable de dévaster des armées entières.', 122820, 'Sangpyre flamboyant', 'Créature : élémental et guerrier', 'Tant que le Sangpyre flamboyant est enchanté, il gagne +2/+2, a le piétinement et « {R} : Le Sangpyre flamboyant gagne +1/+0 jusqu''à la fin du tour. »', 'a172c415-e2ee-56bb-ad04-664dd7910343');
