INSERT INTO `MagicCardRulings` VALUES ('Unlike other Aura spells, an Aura spell with bestow isn’t countered if its target is illegal as it begins to resolve. Rather, the effect making it an Aura spell ends, it loses enchant creature, it returns to being an enchantment creature spell, and it res', '834f3765-b24f-59c1-9309-f0bcc131255f', '2013-09-15', 53348);
