INSERT INTO `MagicCards` (`type`, `language`, `text`, `uuid`, `name`, `flavorText`, `id`, `multiverseid`) VALUES ('Artefact : équipement', 'French', replace('La créature équipée gagne +0/+3 et a la vigilance.\nÉquipement {3} ({3} : Attachez à la créature ciblée que vous contrôlez. N''attachez l''équipement que lorsque vous pourriez lancer un rituel.)','\n',char(10)), '55a8a643-a924-5c96-ad1f-8fc2f2ac1f3f', 'Bouclier cathare', '« Un chef inspire le courage, mais ce sont les forgerons et les guérisseurs qui font vivre l''espoir. » —Thalia, cathare hérétique', 84705, 415390);
