INSERT INTO `rulings_dg_tmp` (`id`, `text`, `uuid`, `date`) VALUES (65625, 'An adventurer card is a creature card in every zone except the stack, as well as while on the stack if not cast as an Adventure. Ignore its alternative characteristics in those cases. For example, while it’s in your graveyard, Giant Killer is a white crea', '21710295-d437-5b12-a1b0-56094ecc1b58', '2019-10-04');
