INSERT INTO (`id`, `date`, `uuid`, `text`) VALUES (46738, '2014-09-20', 'cd110822-4eb9-52a3-a959-9e7ff0c9a8f5', 'Kheru Lich Lord grants flying, trample, and haste to the creature that’s returned to the battlefield. However, neither of the “exile” abilities is granted to that creature. If that creature loses all its abilities, it will still be exiled at the beginning');
